def premier(x):
    nb=0
    for i in range(1,x+1):
        if x%i==0:
            nb=nb+1
    return nb==2
def primoriel(x):
    f=1
    for i in range(1,x+1):
        if (premier (i)):
            f=f*i
    return f
def prem_prim(n):
    x=0
    while (premier(n) and primoriel(x)+1<n and primoriel(x)-1<n):
        x=x+1
    return (premier(n) and (primoriel(x)+1==n or primoriel(x)-1==n))

print(prem_prim(29))

